<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';
$user=club_require_login();$id=isset($_GET['id'])?(int)$_GET['id']:null;$row=$id?club_community_record('post',$id):null;
if(($id&&(!$row||!club_content_editable($row)))||(!$id&&!club_can('content.submit')&&!club_can('content.publish'))){http_response_code(403);exit('You cannot edit this post.');}
$values=$row??['title'=>'','content'=>'','summary'=>'','cover_attachment_id'=>null];$error='';$pendingRevisionId=null;
if($id&&$row['status']==='published'){if($pending=club_editor_revision($id)){$pendingRevisionId=(int)$pending['id'];$values=array_merge($values,json_decode($pending['payload'],true));}}
if($_SERVER['REQUEST_METHOD']==='POST'){
 csrf_verify();$values=array_merge($values,array_intersect_key($_POST,array_flip(['title','content','summary','cover_attachment_id'])));
 try{$saved=club_content_save('post',$id,$_POST,($_POST['action']??'')==='submit',$_FILES['attachments']??[]);
  if(($_SERVER['HTTP_ACCEPT']??'')==='application/json'){$freshSession=club_editor_validate((int)$_POST['editor_session_id'],(string)$_POST['editor_session_token'],(int)$saved['id']);header('Content-Type: application/json');echo json_encode(['id'=>$saved['id'],'status'=>$saved['status'],'url'=>site_url('/members/post-edit.php?id='.$saved['id']),'saved_at'=>date('H:i'),'editor_version'=>club_editor_version((int)$saved['id']),'media'=>club_editor_media($freshSession)],JSON_THROW_ON_ERROR);exit;}
  flash_success($saved['status']==='submitted'?'Your article is awaiting committee approval.':'Your draft has been saved.');redirect('/members/posts.php');
 }catch(Throwable $e){$error=$e instanceof InvalidArgumentException||$e instanceof RuntimeException?$e->getMessage():'We could not save your article. Please try again.';if(($_SERVER['HTTP_ACCEPT']??'')==='application/json'){http_response_code(422);header('Content-Type: application/json');echo json_encode(['error'=>$error]);exit;}}
}
if($_SERVER['REQUEST_METHOD']==='POST'&&!empty($_POST['editor_session_id'])){$editorSession=club_editor_validate((int)$_POST['editor_session_id'],(string)($_POST['editor_session_token']??''),$id);$editorSession['token']=(string)$_POST['editor_session_token'];}else $editorSession=club_editor_start($id);
$media=club_editor_media($editorSession);$initialHtml=club_editor_sanitize($values['content'],array_column($media,'id'),false);
$canAutosave=!$row||in_array($row['status'],['draft','rejected'],true);
club_member_layout_start($id?'Edit your article':'Write an article');
?>
